CREATE SEQUENCE ticket_ids OPTIONS (sequence_kind = 'bit_reversed_positive');

CREATE TABLE singers (
  singer_id INT64 NOT NULL,
  first_name STRING(1024),
  last_name STRING(1024) NOT NULL,
  full_name STRING(2048) NOT NULL AS (ARRAY_TO_STRING([first_name, last_name], ' ')) STORED,
  active BOOL NOT NULL DEFAULT (true),
  updated_at TIMESTAMP NOT NULL OPTIONS (allow_commit_timestamp = true),
  name_tokens TOKENLIST AS (TOKENIZE_FULLTEXT(last_name)) HIDDEN,
) PRIMARY KEY (singer_id);

CREATE TABLE albums (
  singer_id INT64 NOT NULL,
  album_id INT64 NOT NULL,
  title STRING(MAX),
  created_at TIMESTAMP,
  CONSTRAINT title_not_empty CHECK (title != ''),
) PRIMARY KEY (singer_id, album_id),
  INTERLEAVE IN PARENT singers ON DELETE CASCADE,
  ROW DELETION POLICY (OLDER_THAN(created_at, INTERVAL 30 DAY));

CREATE TABLE tickets (
  ticket_id INT64 NOT NULL DEFAULT (GET_NEXT_SEQUENCE_VALUE(SEQUENCE ticket_ids)),
  singer_id INT64 NOT NULL,
  seat_id INT64 GENERATED BY DEFAULT AS IDENTITY (BIT_REVERSED_POSITIVE),
  embedding ARRAY<FLOAT32>(vector_length=>3),
  CONSTRAINT fk_singer FOREIGN KEY (singer_id) REFERENCES singers (singer_id),
) PRIMARY KEY (ticket_id);

CREATE INDEX albums_by_title ON albums(title);
CREATE UNIQUE NULL_FILTERED INDEX singers_by_last_name ON singers(last_name) STORING (first_name);
CREATE SEARCH INDEX singers_by_name_tokens ON singers(name_tokens);
CREATE VECTOR INDEX tickets_by_embedding ON tickets(embedding) WHERE embedding IS NOT NULL OPTIONS (distance_type = 'COSINE');

CREATE CHANGE STREAM everything FOR ALL;
CREATE CHANGE STREAM singer_changes FOR singers(first_name, last_name) OPTIONS (retention_period = '7d');

CREATE ROLE reader;
GRANT SELECT ON TABLE singers, albums TO ROLE reader;

ALTER TABLE albums REPLACE ROW DELETION POLICY (OLDER_THAN(created_at, INTERVAL 60 DAY));
